      await page.goto(`${treemapUrl}?debug`, {
        waitUntil: 'networkidle0',
        timeout: 30000,
      });

      const captionInfo = await page.evaluate(() => {
        const rootNode = document.querySelector('.webtreemap-node--root');
        const rootCaption = rootNode ? rootNode.querySelector(':scope > .webtreemap-caption') : null;
        const captions = Array.from(document.querySelectorAll('.webtreemap-caption'));
        const spanCounts = captions.map(el => el.querySelectorAll('span').length);
        return {
          hasRootCaption: Boolean(rootCaption),
          totalCaptions: captions.length,
          spanCounts,
        };
      });

      expect(captionInfo.totalCaptions).toBeGreaterThan(0);
      expect(captionInfo.hasRootCaption).toBe(false);
      expect(captionInfo.spanCounts.every(count => count >= 2)).toBe(true);
    });

    it('applies depth-dependent background colors to nested bundle nodes', async () => {
      await page.goto(`${treemapUrl}?debug`, {
        waitUntil: 'networkidle0',
        timeout: 30000,
      });

      const colors = await page.evaluate(() => {
        const nodesWithChildren = Array.from(document.querySelectorAll('.webtreemap-node')).filter(el => {
          return el.querySelector('.webtreemap-node') !== null;
        });
        for (const parent of nodesWithChildren) {
          const child = parent.querySelector('.webtreemap-node');
          if (!child) continue;
          const parentBg = window.getComputedStyle(parent).backgroundColor;
          const childBg = window.getComputedStyle(child).backgroundColor;
          if (parentBg && childBg && parentBg !== 'transparent' && childBg !== 'transparent') {
            return {parentBg, childBg};
          }
        }
        return null;
      });

      expect(colors).not.toBeNull();
      expect(colors.parentBg).not.toBe(colors.childBg);
    });
  });
});
